text:
Lab: readability checker


Lab · runs in your browser; your text does not leave it

Paste a paragraph. The lab estimates the Flesch Reading Ease score (higher = easier; most scientific abstracts score below 30), the average sentence length, and highlights nominalisations, passive constructions and wordy phrases.

area = window.Lab.area
viewof parrafo = area("Your text", {rows: 7, submit: "Analyse", value: "In order to perform an evaluation of the effectiveness of the intervention, an analysis of the data was conducted by the research team. It was found that there was a significant reduction in attrition due to the fact that supervision meetings were held more frequently. The implementation of the programme is recommended."})
















{
  const t = parrafo || "";
  const frases = t.replace(/\s+/g, " ").split(/(?&lt;=[.!?])\s+/).filter(f =&gt; f.trim());
  const palabras = t.toLowerCase().match(/[a-z']+/g) || [];
  const sil = w =&gt; { w = w.replace(/e$/, ""); const m = w.match(/[aeiouy]+/g); return Math.max(1, m ? m.length : 1); };
  const nP = palabras.length || 1, nF = Math.max(1, frases.length), nS = palabras.reduce((s, w) =&gt; s + sil(w), 0);
  const fre = 206.835 - 1.015 * (nP / nF) - 84.6 * (nS / nP);
  const esc = s =&gt; s.replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const prolijas = {"in order to": "to", "due to the fact that": "because", "a large number of": "many", "in spite of the fact that": "although", "at this point in time": "now", "it is important to note that": "(delete)", "with regard to": "about", "a majority of": "most", "conduct an analysis of": "analyse", "perform an evaluation of": "evaluate"};
  let marcado = esc(t);
  marcado = marcado.replace(/\b(\w+(?:tion|ment|ance|ence|sis))\b/gi, '&lt;mark title="nominalisation"&gt;$1&lt;/mark&gt;');
  marcado = marcado.replace(/\b(was|were|is|are|been|be|being)\s+(\w+ed|found|held|made|done|shown|seen|given|taken)\b/gi, '&lt;u title="passive"&gt;$1 $2&lt;/u&gt;');
  const vistas = Object.keys(prolijas).filter(k =&gt; t.toLowerCase().includes(k));
  const nivel = fre &gt;= 60 ? "plain English" : fre &gt;= 30 ? "fairly difficult" : "very difficult (typical of scientific prose)";
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;ul&gt;&lt;li&gt;Flesch Reading Ease: &lt;strong&gt;${fre.toFixed(0)}&lt;/strong&gt; · ${nivel}&lt;/li&gt;&lt;li&gt;${nF} sentences · &lt;strong&gt;${(nP / nF).toFixed(1)}&lt;/strong&gt; words per sentence&lt;/li&gt;&lt;/ul&gt;
   &lt;p style="line-height:1.9"&gt;${marcado}&lt;/p&gt;
   &lt;p class="small"&gt;&lt;mark&gt;highlighted&lt;/mark&gt; = possible nominalisation · &lt;u&gt;underlined&lt;/u&gt; = possible passive&lt;/p&gt;
   ${vistas.length ? `&lt;p class="lab-medio" style="font-weight:600"&gt;Wordy phrases: ${vistas.map(k =&gt; `«${k}» → «${prolijas[k]}»`).join("; ")}&lt;/p&gt;` : '&lt;p class="lab-bien" style="font-weight:600"&gt;No common wordy phrases found.&lt;/p&gt;'}
   &lt;p class="small"&gt;These are heuristics: not every -tion word or passive is a problem. Use them to look again, not as rules.&lt;/p&gt;`;
  return d;
}

Lab: hedges and boosters


Lab · runs in your browser; your text does not leave it


area = window.Lab.area
viewof texto_h = area("Your text", {rows: 6, submit: "Analyse", value: "Our results clearly demonstrate that mentoring causes higher completion rates. This finding is undoubtedly important for doctoral programmes. However, the effect may differ across disciplines, and it is possible that more motivated students sought mentors."})
















{
  const hedges = ["may", "might", "could", "possibly", "perhaps", "likely", "unlikely", "suggest", "suggests", "indicate", "indicates", "appear", "appears", "seem", "seems", "probably", "it is possible", "tend to", "to some extent", "approximately", "relatively"];
  const boosters = ["clearly", "demonstrate", "demonstrates", "undoubtedly", "certainly", "prove", "proves", "obviously", "definitely", "always", "never", "it is well known", "establish", "establishes", "show that", "shows that", "causes", "cause"];
  const esc = s =&gt; s.replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  let m = esc(texto_h || ""); let nh = 0, nb = 0;
  const marca = (lista, estilo, cuenta) =&gt; { for (const w of lista.sort((a, b) =&gt; b.length - a.length)) { const re = new RegExp(`\\b(${w.replace(/ /g, "\\s+")})\\b`, "gi"); m = m.replace(re, x =&gt; { cuenta(); return `&lt;span style="${estilo}"&gt;${x}&lt;/span&gt;`; }); } };
  marca(hedges, "background:#d6e6f8;color:#0b0b0b;padding:0 2px;border-radius:3px", () =&gt; nh++);
  marca(boosters, "background:#f6dccf;color:#0b0b0b;padding:0 2px;border-radius:3px;font-weight:600", () =&gt; nb++);
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p style="line-height:1.9"&gt;${m}&lt;/p&gt;&lt;p class="small"&gt;&lt;span style="background:#d6e6f8;color:#0b0b0b;padding:0 2px"&gt;blue&lt;/span&gt; = hedge (${nh}) · &lt;span style="background:#f6dccf;color:#0b0b0b;padding:0 2px;font-weight:600"&gt;orange&lt;/span&gt; = booster (${nb})&lt;/p&gt;
   &lt;p class="${nb &gt; nh ? "lab-medio" : "lab-bien"}" style="font-weight:600"&gt;${nb &gt; nh ? "More boosters than hedges: check that the evidence (design, sample, replication) supports such strong claims, especially any causal verbs." : "The text is cautious. Check that it is not over-hedged: one hedge per claim is usually enough."}&lt;/p&gt;`;
  return d;
}

Lab: Spanglish detector


Lab · runs in your browser; your text does not leave it


area = window.Lab.area
viewof borrador = area("Your text", {rows: 6, submit: "Check", value: "Actually, several researches have been realised to contrast this hypothesis. The informations were analysed with differents softwares. Is important to note that the results depend of the sample, which consisted in 1.200 students."})
















{
  const reglas = [
    [/\bresearches\b/gi, "«research» is uncountable: use «studies» or «research»"], [/\binformations\b/gi, "«information» is uncountable"], [/\bevidences\b/gi, "«evidence» is uncountable"],
    [/\bsoftwares\b/gi, "«software» is uncountable: «software tools»"], [/\bequipments\b/gi, "«equipment» is uncountable"], [/\badvices\b/gi, "«advice» is uncountable"], [/\bfeedbacks\b/gi, "«feedback» is uncountable"],
    [/\bactually\b/gi, "False friend? «actually» = in fact; «actualmente» = currently"], [/\bactual\b/gi, "False friend? «actual» = real; «actual» (es) = current"], [/\beventually\b/gi, "False friend? «eventually» = in the end"],
    [/\brealis(?:e|ed|ing)\b|\brealiz(?:e|ed|ing)\b/gi, "False friend? «realise» = become aware; use «conduct/carry out»"], [/\bcontrast(?:ed)?\b(?=\s+(?:this|the|our|a)\s+hypothes)/gi, "Use «test the hypothesis»"],
    [/\bmak(?:e|ing|e a|ed)\s+(?:a\s+)?research\b/gi, "Use «do/conduct research»"], [/\bdifferents\b/gi, "Adjectives have no plural: «different»"], [/(?:^|[.!?]\s+)Is\s/g, "Missing subject: «It is…»"],
    [/\bdepend(?:s|ed|ing)? of\b/gi, "«depend on»"], [/\bconsist(?:s|ed|ing)? in\b/gi, "«consist of»"], [/\binterested on\b/gi, "«interested in»"],
    [/\b\d{1,3}\.\d{3}\b/g, "Thousands separator in English is a comma: 1,200"], [/\b\d+,\d+\s?%/g, "Decimal point in English: 3.5%"], [/\bassist(?:ed)? to\b/gi, "«attend»"]];
  const esc = s =&gt; s.replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const avisos = []; let m = esc(borrador || "");
  for (const [re, msg] of reglas) { const enc = (borrador || "").match(re); if (enc) { avisos.push([enc[0].trim(), msg]); m = m.replace(re, x =&gt; `&lt;mark title="${msg}"&gt;${x}&lt;/mark&gt;`); } }
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p style="line-height:1.9"&gt;${m}&lt;/p&gt;${avisos.length ? `&lt;ul&gt;${avisos.map(([w, msg]) =&gt; `&lt;li&gt;&lt;strong&gt;${esc(w)}&lt;/strong&gt;: ${msg}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : '&lt;p class="lab-bien" style="font-weight:600"&gt;No common errors detected. (The lab checks only a list of frequent errors.)&lt;/p&gt;'}`;
  return d;
}

Lab · runs in your browser

A good abstract moves through five rhetorical moves (Hyland, 2000): introduction, purpose, method, product (results) and conclusion. Paste your abstract. The lab tags each sentence with its most likely move using signal phrases, flags long sentences and lists the moves it could not find. It is a heuristic guide, not a judgement.

areaE = window.Lab.area
viewof abstractTxt = areaE("Your abstract", {rows: 9, value: "Open research data are increasingly required by funders. However, little is known about how researchers in the humanities reuse shared data. This study aims to identify the main barriers to data reuse among humanities scholars. We surveyed 412 researchers in Spain and analysed their responses using latent class analysis. We found that 63% had never reused data and that the lack of documentation was the most frequent barrier. These findings suggest that data policies should invest in documentation and training rather than in mandates alone."})
















{
  const frases = abstractTxt.replace(/\s+/g, " ").trim().split(/(?&lt;=[.!?])\s+(?=[A-Z])/).filter((s) =&gt; s.length &gt; 2);
  const reglas = [
    ["Conclusion", "#6a3d9a", /\b(suggest|conclude|implications?|imply|recommend|should|these (findings|results)|overall|in conclusion)\b/i],
    ["Product", "#1c6b3a", /\b(we found|results? (show|indicate|reveal)|found that|showed|revealed|was associated|were associated|significantly|\d+(\.\d+)?\s?%|p\s?[&lt;=])/i],
    ["Method", "#b35900", /\b(we (surveyed|analysed|analyzed|used|conducted|collected|interviewed|measured|compared|applied|performed)|using|data (from|were)|sample of|participants|questionnaire|regression|analysis)\b/i],
    ["Purpose", "#2a78d6", /\b(this (study|paper|article)|we (aim|investigate|examine|explore|propose|present)|aims? to|the (aim|purpose|goal) of|here,? we)\b/i],
    ["Introduction", "#52514e", /\b(however|little is known|remains? (unclear|unknown)|increasingly|has been|have been|is (a|an|the)|are (a|an)|growing)\b/i]];
  const etiqueta = (s) =&gt; { for (const [m, c, re] of reglas) if (re.test(s)) return [m, c]; return ["Unclear", "#8a8a8a"]; };
  const esc = (s) =&gt; s.replace(/[&&lt;&gt;]/g, (c) =&gt; ({"&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;"}[c]));
  const tags = frases.map((s) =&gt; [s, ...etiqueta(s), s.split(/\s+/).length]);
  const total = abstractTxt.trim() ? abstractTxt.trim().split(/\s+/).length : 0;
  const orden = ["Introduction", "Purpose", "Method", "Product", "Conclusion"];
  const faltan = orden.filter((m) =&gt; !tags.some((t) =&gt; t[1] === m));
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;ol class="list-unstyled"&gt;${tags.map(([s, m, c, n]) =&gt; `&lt;li class="mb-1"&gt;&lt;span class="badge" style="background:${c};color:#fff;min-width:7.5em"&gt;${m}&lt;/span&gt; ${esc(s)} ${n &gt; 30 ? `&lt;span class="small text-danger"&gt;⚠ ${n} words: consider splitting&lt;/span&gt;` : ""}&lt;/li&gt;`).join("")}&lt;/ol&gt;
  &lt;p&gt;&lt;strong&gt;${total} words&lt;/strong&gt; ${total &gt; 250 ? "· ⚠ over 250: most journals will ask you to cut it" : total &lt; 100 ? "· quite short: check that every move is there" : "· a typical length (100–250)"}.&lt;/p&gt;
  &lt;p&gt;${faltan.length ? `Moves not detected: &lt;strong&gt;${faltan.join(", ")}&lt;/strong&gt;. Check whether they are missing or just phrased without the usual signals.` : "All five moves detected. Check that they appear in a logical order."}&lt;/p&gt;`;
  return d;
}

Lab: response to reviewers


Lab · runs in your browser

A good response letter quotes each comment, thanks the reviewer briefly, says what you changed and where, and disagrees politely with evidence when needed. Fill in one comment and copy the formatted reply.

{
  const raiz = html`&lt;div class="resp-lab"&gt;&lt;/div&gt;`;
  const campo = (id, et, val, area) =&gt; { const d = html`&lt;div class="mb-2"&gt;&lt;label class="form-label" for="${id}"&gt;${et}&lt;/label&gt;${area ? `&lt;textarea id="${id}" class="form-control form-control-sm" rows="3"&gt;${val}&lt;/textarea&gt;` : `&lt;input id="${id}" class="form-control form-control-sm" value="${val}"&gt;`}&lt;/div&gt;`; raiz.append(d); return d.querySelector("input, textarea"); };
  const com = campo("rr-com", "Reviewer comment", "The sample size seems small and the authors do not justify it.", true);
  const acc = html`&lt;div class="mb-2"&gt;&lt;label class="form-label" for="rr-acc"&gt;Your decision&lt;/label&gt;&lt;select id="rr-acc" class="form-select form-select-sm"&gt;&lt;option&gt;We agree and have changed the manuscript&lt;/option&gt;&lt;option&gt;We partly agree&lt;/option&gt;&lt;option&gt;We respectfully disagree&lt;/option&gt;&lt;/select&gt;&lt;/div&gt;`; raiz.append(acc);
  const cam = campo("rr-cam", "What you did (or your evidence)", "We added a power analysis showing that 120 participants give 80% power to detect d = 0.5, and we discuss this limitation.", true);
  const loc = campo("rr-loc", "Where (section, page, lines)", "Methods, p. 7, lines 142-150");
  const salida = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  const esc = (s) =&gt; s.replace(/[&&lt;&gt;]/g, (c) =&gt; ({"&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;"}[c]));
  function act() {
    const dec = acc.querySelector("select").value;
    const inicio = dec.startsWith("We agree") ? "Thank you for this helpful comment. We agree," : dec.startsWith("We partly") ? "Thank you for raising this point. We agree in part:" : "We thank the reviewer for this comment. We have considered it carefully, but we respectfully disagree, because";
    const cuerpo = cam.value.trim().replace(/^we /i, "we ");
    const texto = `**Comment 1.** "${com.value.trim()}"\n\n**Response.** ${inicio} ${cuerpo.charAt(0).toLowerCase() + cuerpo.slice(1)}${loc.value.trim() ? ` (${loc.value.trim()})` : ""}`;
    const avisos = [];
    if (/\b(wrong|misunderstood|clearly|obviously|failed to|did not read)\b/i.test(cam.value)) avisos.push("Your reply contains words that may sound defensive (wrong, clearly, obviously…). Rephrase neutrally.");
    if (!loc.value.trim() && !dec.includes("disagree")) avisos.push("Say where the change is (section, page, lines): editors check it.");
    if (cam.value.trim().split(/\s+/).length &lt; 8) avisos.push("The reply is very short: explain what you changed or why you disagree.");
    if (dec.includes("disagree") && !/\b(because|evidence|data|study|studies|shown|show)\b/i.test(cam.value)) avisos.push("When you disagree, support it with evidence (data, references).");
    salida.innerHTML = `&lt;div class="p-3 border rounded"&gt;&lt;p class="mb-1"&gt;&lt;strong&gt;Comment 1.&lt;/strong&gt; “${esc(com.value.trim())}”&lt;/p&gt;&lt;p class="mb-0"&gt;&lt;strong&gt;Response.&lt;/strong&gt; ${esc(texto.split("**Response.** ")[1])}&lt;/p&gt;&lt;/div&gt;${avisos.length ? `&lt;ul class="mt-2"&gt;${avisos.map((a) =&gt; `&lt;li&gt;⚠ ${a}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : '&lt;p class="small mt-2"&gt;✓ Clear, polite and located.&lt;/p&gt;'}&lt;button type="button" class="btn btn-outline-primary btn-sm"&gt;Copy as Markdown&lt;/button&gt; &lt;span class="small"&gt;&lt;/span&gt;`;
    salida.querySelector("button").onclick = () =&gt; navigator.clipboard?.writeText(texto).then(() =&gt; salida.querySelector("span").textContent = "Copied.", () =&gt; salida.querySelector("span").textContent = "Copy failed: select the text manually.");
  }
  raiz.addEventListener("input", act); raiz.append(salida); act();
  return raiz;
}

Lab: cover letter


Lab · runs in your browser

Editors read the cover letter in a minute. It should say what you found, why it matters for this journal and confirm the required declarations. Fill in the fields and download the draft.

{
  const raiz = html`&lt;div class="cover-lab"&gt;&lt;/div&gt;`;
  const campo = (id, et, val) =&gt; { const d = html`&lt;div class="mb-2"&gt;&lt;label class="form-label" for="${id}"&gt;${et}&lt;/label&gt;&lt;input id="${id}" class="form-control form-control-sm" value="${val}"&gt;&lt;/div&gt;`; raiz.append(d); return d.querySelector("input"); };
  const ed = campo("cl-ed", "Editor's name (if known)", "Dr Smith");
  const rev = campo("cl-rev", "Journal", "Quantitative Science Studies");
  const tit = campo("cl-tit", "Manuscript title", "Policy citations capture a different kind of research impact");
  const tipo = campo("cl-tipo", "Article type", "Research article");
  const hall = campo("cl-hall", "Main finding (one sentence)", "policy citations are only weakly correlated with academic citations across 15,000 articles");
  const enc = campo("cl-enc", "Why it fits this journal", "it addresses research evaluation indicators, a central topic of the journal");
  const decl = html`&lt;fieldset class="mb-2"&gt;&lt;legend class="form-label"&gt;Declarations&lt;/legend&gt;${["The manuscript is not under consideration elsewhere", "All authors approved the submission", "There are no competing interests", "Data and code are openly available"].map((x, i) =&gt; `&lt;div class="form-check"&gt;&lt;input class="form-check-input" type="checkbox" id="cl-d${i}" checked&gt;&lt;label class="form-check-label" for="cl-d${i}"&gt;${x}&lt;/label&gt;&lt;/div&gt;`).join("")}&lt;/fieldset&gt;`;
  raiz.append(decl);
  const salida = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  const esc = (s) =&gt; s.replace(/[&&lt;&gt;]/g, (c) =&gt; ({"&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;"}[c]));
  function act() {
    const ds = [...decl.querySelectorAll("input")].filter((x) =&gt; x.checked).map((x) =&gt; x.nextElementSibling.textContent);
    const carta = `Dear ${ed.value.trim() || "Editor"},\n\nPlease consider our manuscript "${tit.value.trim()}" for publication as a ${tipo.value.trim().toLowerCase()} in ${rev.value.trim()}.\n\nWe show that ${hall.value.trim()}. We believe the manuscript is a good fit for ${rev.value.trim()} because ${enc.value.trim()}.\n\n${ds.map((x) =&gt; x + ".").join(" ")}\n\nThank you for your consideration.\n\nYours sincerely,\n[Name, affiliation, ORCID]`;
    const n = carta.split(/\s+/).length;
    const url = URL.createObjectURL(new Blob([carta], {type: "text/plain"}));
    const avisos = [];
    if (!/\d/.test(hall.value)) avisos.push("Add a number to the main finding: concrete results catch the editor's attention.");
    if (ds.length &lt; 2) avisos.push("Most journals require you to confirm originality and author approval.");
    salida.innerHTML = `&lt;pre class="p-3 border rounded" style="white-space:pre-wrap"&gt;${esc(carta)}&lt;/pre&gt;&lt;p class="small"&gt;${n} words${n &gt; 250 ? " · consider shortening: one screen is enough" : ""}.&lt;/p&gt;${avisos.length ? `&lt;ul&gt;${avisos.map((a) =&gt; `&lt;li&gt;⚠ ${a}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : ""}&lt;a class="btn btn-outline-primary btn-sm" download="cover-letter.txt" href="${url}"&gt;Download (.txt)&lt;/a&gt;`;
  }
  raiz.addEventListener("input", act); raiz.append(salida); act();
  return raiz;
}
